class MinStack {
  // Сами значения
  private values: number[] = [];
  // mins[i] — минимум среди values[0..i], то есть минимум стека,
  // когда на вершине лежит values[i]
  private mins: number[] = [];

  constructor() {}

  push(value: number): void {
    this.values.push(value);
    // Новый минимум — меньшее из нового значения и прежнего минимума
    const prevMin = this.mins.length > 0 ? this.mins[this.mins.length - 1] : value;
    this.mins.push(Math.min(value, prevMin));
  }

  pop(): void {
    // Снимаем значение вместе с «его» минимумом — прежний минимум восстанавливается сам
    this.values.pop();
    this.mins.pop();
  }

  top(): number {
    return this.values[this.values.length - 1];
  }

  getMin(): number {
    // Минимум всего стека хранится на вершине mins
    return this.mins[this.mins.length - 1];
  }
}

// Время: O(1) на каждую операцию
// Память: O(n) — два массива по n элементов
